        format!("Hello, {} year old named {} !, {}", age, name, self.cache)
    }
}

fn main() {
    let index = Index::new("Cache data");
    rocket::ignite().mount("/", routes![index.handler]).launch();
}

```

But the macro get & routes don't support for this case. So how to implement it in case rounting handler need access context data such as cache or configure?

