    HttpResponse::Ok()
        .streaming(stream! {
            let mut count = 0;
            while count < 10 {
                yield Ok::<_, Infallible>(Bytes::from(count.to_string()));
                thread::sleep(Duration::from_millis(250));
                count += 1;
            }
        })

}
