>             inner: None,
>         })),
>     });
> 
>     let r: Store<Box<HeaderState>, _> = header.inner().unwrap();
> ```

You can get to the title by calling deref and then title like this:
```rust

#[derive(Store)]
struct HeaderState {
    title: String,
    subtitle: String,
    inner: Option<Box<HeaderState>>,
}

fn app() -> Element {
    let header = use_store(|| HeaderState {
        title: "Hello, ".to_string(),
        subtitle: "world!".to_string(),
        inner: Some(Box::new(HeaderState {
            title: "Hello, ".to_string(),
            subtitle: "world!".to_string(),
            inner: None,
        })),
    });

    let title: Store<String, _> = header.inner().unwrap().deref().title();

    rsx! {
        div {
            "{title}"
        }
    }
}
```

We need an explicit deref method both because we don't have a reference to the version of the deref mapped store object to return a reference to and we already have a deref implementation for the callable api

